using namespace std;

int main() {
    int n;
    cin >> n;
    vector<double> max_p(n);
    vector<double> min_p(n);
    for (int i = 0; i < n; ++i) {
        cin >> max_p[i];
    }
    for (int i = 0; i < n; ++i) {
        cin >> min_p[i];
    }

    vector<double> a(n), b(n);
    for (int i = 0; i < n; ++i) {
        a[i] = max_p[i] - min_p[i];
        b[i] = min_p[i] - max_p[i];
    }

    // Handle the case where a[i] or b[i] could be negative due to floating point precision
    for (int i = 0; i < n; ++i) {
        if (a[i] < 0) a[i] = 0;
        if (b[i] < 0) b[i] = 0;
    }

    // Adjust the probabilities for the first and second dice
    double sum_a = 0, sum_b = 0;
    for (int i = 0; i < n; ++i) {
        sum_a += a[i];
        sum_b += b[i];
    }

    for (int i = 0; i < n; ++i) {
        a[i] /= sum_a;
        b[i] /= sum_b;
    }

    // Now, we need to handle the case where the sum of a and b isn't exactly 1 due to rounding
    // We can distribute the remaining probability to the last element
    double remaining_a = 1 - sum_a;
    double remaining_b = 1 - sum_b;
    a[n-1] += remaining_a;
    b[n-1] += remaining_b;

    for (int i = 0; i < n; ++i) {
        cout << fixed << setprecision(10) << a[i] << " ";
    }
    cout << endl;
    for (int i = 0; i < n; ++i) {
        cout << fixed << setprecision(10) << b[i] << " ";
    }
    cout << endl;

