        long long max_val = max_heap.top();
        long long min_val = min_heap.top();

        if (max_val == min_val) break;

        max_heap.pop();
        min_heap.pop();

        long long diff = max_val - min_val;
        long long transfers = diff / (n - 1);
        long long remaining = diff % (n - 1);

