#include <iostream>
#include <vector>
#include <queue>
#include <unordered_map>
using namespace std;

int main() {
    int n;
    cin >> n;
    vector<long long> a(n);
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
    }

    if (n == 1) {
        cout << 0 << endl;
        return 0;
    }

    queue<int> q;
    unordered_map<long long, int> balanceToCount;
    q.push(0);
    balanceToCount[a[0]] = 1;

    while (!q.empty()) {
        int i = q.front();
        q.pop();
        long long curr = a[i];
        if (curr == 0) continue;

        if (i > 0) {
            long long next = a[i - 1];
            a[i - 1] += curr;
            a[i] -= curr;
            balanceToCount[next] -= 1;
            if (balanceToCount[next] == 0) balanceToCount.erase(next);
            balanceToCount[a[i - 1]] += 1;
            if (balanceToCount[a[i - 1]] == 1) q.push(i - 1);
        }

        if (i < n - 1) {
            long long next = a[i + 1];
            a[i + 1] += curr;
            a[i] -= curr;
            balanceToCount[next] -= 1;
            if (balanceToCount[next] == 0) balanceToCount.erase(next);
            balanceToCount[a[i + 1]] += 1;
            if (balanceToCount[a[i + 1]] == 1) q.push(i + 1);
        }
    }

    cout << balanceToCount.size() - 1 << endl;
    return 0;
}

