        cin >> a[i];
    }

    if (n == 1) {
        cout << 0;
        return 0;
    }

    // Using a queue to simulate the process
    queue<int> q;
    vector<long long> balances(n);
    for (int i = 0; i < n; ++i) {
        balances[i] = a[i];
        if (a[i] != 0) {
            q.push(i);
        }
    }

    int operations = 0;
    while (!q.empty()) {
        int i = q.front();
        q.pop();

        // Transfer the balance from bank i to its neighbor with the smallest index
        long long amount = balances[i];
        int j = (i + 1) % n;
        if (amount == 0) continue;

        balances[i] = 0;
        balances[j] += amount;
        operations++;

        // If the neighbor now has a non-zero balance, add it to the queue
        if (balances[j] != 0) {
            q.push(j);
        }
    }

    cout << operations;
    return 0;
}

