long long solve(int n, vector<long long>& a) {
    long long res = 0;
    long long prev = 0;
    for (int i = 0; i < n; ++i) {
        long long curr = a[i];
        if (i == n - 1) {
            // Last bank has no next neighbor, so we can't transfer beyond it
            // We need to transfer the accumulated value to the first bank
            res += abs(curr);
        } else {
            // Transfer the amount to the next bank
            res += abs(curr - prev);
            prev = curr;
        }
    }
    return res;
}

