#include <iostream>
#include <vector>
#include <deque>
using namespace std;

long long solve(int n, vector<long long>& a) {
    deque<long long> dq(a.begin(), a.end());
    long long res = 0;
    while (!dq.empty()) {
        long long curr = dq.front();
        dq.pop_front();
        if (curr == 0)
            continue;
        long long next = dq.front();
        dq.pop_front();
        dq.push_front(curr + next);
        res++;
    }
    return res;
}

int main() {
    int n;
    cin >> n;
    vector<long long> a(n);
    for (int i = 0; i < n; i++)
        cin >> a[i];
    cout << solve(n, a) << endl;
    return 0;
}

