    long long a = cube_root(m);
    while (a >= 1) {
        long long vol = a * a * a;
        if (total + vol > m) {
            --a;
            continue;
        }
        long long rem = m - total;
        long long max_k = rem / (a * a);
        total += max_k * vol;
        count += max_k;
        max_x = total;
        a = cube_root(rem);
    }

    cout << max_count << " " << max_x << endl;
    return 0;
}

long long cube_root(long long x) {
    long long low = 1, high = 1000000000;
    while (low <= high) {
        long long mid = (low + high) / 2;
        long long cube = mid * mid * mid;
        if (cube == x) return mid;
        else if (cube < x) low = mid + 1;
        else high = mid - 1;
    }
    return high;
}

