    queue<int> q;
    int cnt = 0;

    for (int i = 1; i <= n; ++i) {
        if (color[i] == -1) {
            color[i] = 0;
            q.push(i);
            ++cnt;
            while (!q.empty()) {
                int u = q.front();
                q.pop();
                for (int v : adj[u]) {
                    if (color[v] == -1) {
                        color[v] = color[u] ^ 1;
                        q.push(v);
                    }
                }
            }
        }
    }

    if (cnt != 2) {
        cout << -1 << endl;
        return 0;
    }

    vector<int> A, B;
    for (int i = 1; i <= n; ++i) {
        if (color[i] == 0) A.push_back(i);
