    bool isAcover = true, isBcover = true;
    for (int u = 1; u <= n; ++u) {
        for (int v : adj[u]) {
            if (color[u] == 0 && color[v] == 0) {
                isAcover = false;
                break;
            }
            if (color[u] == 1 && color[v] == 1) {
                isBcover = false;
                break;
            }
        }
        if (!isAcover || !isBcover) break;
