#include <functional>

using namespace std;

int main() {
    int x, y;
    cin >> x >> y;

    unordered_map<int, int> memo;
    queue<pair<int, int>> q;
    q.push({x, 0});
    memo[x] = 0;

    while (!q.empty()) {
        auto [current, steps] = q.front();
        q.pop();

        if (current == y) {
            cout << steps;
            return 0;
        }

        // Reduce the largest side by 1 each time
        int next = current - 1;
        if (next > 0 && memo.find(next) == memo.end()) {
            memo[next] = steps + 1;
            q.push({next, steps + 1});
        }

        // Try reducing one side by 1 and adjust others to maintain non-degenerate triangle
        // We can only reduce one side, so we consider all possible sides
        // For an equilateral triangle, all sides are equal, so we can reduce any one side
        // After reducing one side, the triangle becomes (current-1, current, current)
        // To keep it non-degenerate, the smallest side must be greater than 0 and the sum of any two sides must be greater than the third
        // Since it's still isosceles, it's enough to ensure current - 1 + current > current => which is always true if current > 1
        // So we can generate a new triangle with one side reduced by 1 and other two same
        // But since we want to reach y, we can consider only the case where the side is reduced to y
        if (current > y) {
            int new_len = current - 1;
            if (new_len > 0 && memo.find(new_len) == memo.end()) {
                memo[new_len] = steps + 1;
                q.push({new_len, steps + 1});
            }
        }
    }

    cout << -1;
    return 0;
}

