        vector<vector<pair<int, ll>>> adj2(n);
        for (int i = 0; i < m; ++i) {
            int u = edges[i].first;
            int v = edges[i].second;
            ll w = edges[i].third;
            if (w != 0) {
                adj2[u].push_back({v, w});
                adj2[v].push_back({u, w});
            }
        }

        // Use BFS to find the shortest path with minimal number of missing edges
        vector<int> prev(n, -1);
        vector<int> dist2(n, INF);
        dist2[s] = 0;
        queue<int> q;
        q.push(s);

        while (!q.empty()) {
            int u = q.front();
            q.pop();
            for (auto& [v, w] : adj2[u]) {
                if (dist2[v] > dist2[u] + w) {
                    dist2[v] = dist2[u] + w;
                    prev[v] = u;
                    q.push(v);
                }
            }
        }

        if (dist2[t] == INF) {
            // No path exists with known weights
            cout << "NO" << endl;
            return 0;
        }

        // Find the path from s to t
        vector<int> path;
        for (int v = t; v != -1; v = prev[v]) {
            path.push_back(v);
        }
        reverse(path.begin(), path.end());

        // Calculate total length of the path
        ll path_len = 0;
        for (int i = 1; i < path.size(); ++i) {
            int u = path[i-1], v = path[i];
            for (auto& [u2, v2, w] : edges) {
                if ((u2 == u && v2 == v) || (u2 == v && v2 == u)) {
                    if (w == 0) {
                        path_len += 1;
                    } else {
                        path_len += w;
                    }
                    break;
                }
            }
        }

        // Calculate how much we need to add to the path to reach L
        ll need = L - path_len;
        if (need < 0) {
            cout << "NO" << endl;
            return 0;
        }

        // Distribute the need among the missing edges on the path
        int cnt = 0;
        for (int i = 1; i < path.size(); ++i) {
            int u = path[i-1], v = path[i];
            for (auto& [u2, v2, w] : edges) {
                if ((u2 == u && v2 == v) || (u2 == v && v2 == u)) {
                    if (w == 0) {
                        w += 1;
                        need--;
                        if (need == 0) break;
                    }
                }
            }
        }

        if (need != 0) {
            cout << "NO" << endl;
            return 0;
        }

        // Output the edges
        cout << "YES" << endl;
        for (auto& [u, v, w] : edges) {
