    for (int i = 1; i < n; ++i) {
        pq.push({i, '0'});
    }

    while (pq.size() > 1) {
        auto left = pq.top();
        pq.pop();
        auto right = pq.top();
        pq.pop();

        int combined = left.first + right.first;
        totalCost += combined * (left.bit == '0' ? c0 : c1);
        totalCost += combined * (right.bit == '0' ? c0 : c1);

        pq.push({combined, '1'});
