using namespace std;

int main() {
    int n, c0, c1;
    cin >> n >> c0 >> c1;

    // If c0 is cheaper, use 0 as the cheaper bit, else use 1
    if (c0 < c1) {
        swap(c0, c1);
    }

    // The optimal way is to use a prefix code where the more frequent symbols have shorter codes
    // Since we need to minimize cost and the problem is about building a prefix code for n symbols,
    // we can treat this as a Huffman coding problem with the cost of each bit.
    // However, since all codes need to be unique and prefix-free, the optimal is to use binary codes
    // of lengths 1, 2, ..., k such that the total number of symbols is n.

    // The total number of bits used is n * (length of the binary code) - (n - 1) * 1
    // The optimal code is to use binary codes of lengths such that the total number of symbols is n
    // and the total cost is minimized.

    int totalCost = 0;
    int bits = 0;

    // Find the minimum number of bits needed for n symbols
    // Using binary codes of lengths 1, 2, ..., k
    int k = 0;
    int sum = 0;
    while (sum < n) {
        sum += (1 << k);
        k++;
    }

    // Now find the number of symbols with code length k-1
    int prevSum = 0;
    for (int i = 0; i < k - 1; i++) {
        prevSum += (1 << i);
    }
    int numWithKBits = n - prevSum;

