vector<string> split(const string& str, char delimiter) {
    vector<string> result;
    string token;
    for (char c : str) {
        if (c == delimiter) {
            if (!token.empty()) {
                result.push_back(token);
                token.clear();
            }
        } else {
            token += c;
        }
    }
    if (!token.empty()) {
