#include <vector>
#include <unordered_map>
using namespace std;

int main() {
    int n;
    cin >> n;
    string s;
    cin >> s;

    vector<int> visited(n + 2, 0); // 1-based indexing, 0 and n+1 are out of bounds
    unordered_map<int, int> memo;

    function<int(int)> dfs = [&](int i) {
        if (i < 1 || i > n) return 1; // falls from the game
        if (visited[i]) return 0; // already visited, loop detected
        visited[i] = 1;
        int next = (s[i - 1] == '>' ? i + 1 : i - 1);
        if (memo.find(next) != memo.end()) {
            return memo[next];
        }
        int res = dfs(next);
        memo[i] = res;
        return res;
    };

    int count = 0;
    for (int i = 1; i <= n; ++i) {
        if (dfs(i) == 1) ++count;
    }

    cout << count << endl;
    return 0;
}

