#include <bits/stdc++.h>
using namespace std;

int main() {
    int n, m;
    cin >> n >> m;
    vector<string> grid(n);
    for (int i = 0; i < n; ++i) {
        cin >> grid[i];
    }

    set<pair<int, int>> x_coords;
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            if (grid[i][j] == 'X') {
                x_coords.insert({i, j});
            }
        }
    }

    int min_row = min_element(x_coords.begin(), x_coords.end(), [](auto a, auto b) { return a.first < b.first; })->first;
    int max_row = max_element(x_coords.begin(), x_coords.end(), [](auto a, auto b) { return a.first < b.first; })->first;
    int min_col = min_element(x_coords.begin(), x_coords.end(), [](auto a, auto b) { return a.second < b.second; })->second;
    int max_col = max_element(x_coords.begin(), x_coords.end(), [](auto a, auto b) { return a.second < b.second; })->second;

    int height = max_row - min_row + 1;
    int width = max_col - min_col + 1;

    int total_x = x_coords.size();
    if (total_x % 2 != 0) {
        cout << "NO";
        return 0;
    }

    int required_width = 2 * width;
    int required_height = 2 * height;

    if (required_height > n || required_width > m) {
        cout << "NO";
        return 0;
    }

    // Check if we can place the piece in such a way that it forms a rectangle
    // with another copy by shifting it horizontally or vertically
    bool possible = false;
    for (int dx = 0; dx < m; ++dx) {
        for (int dy = 0; dy < n; ++dy) {
            set<pair<int, int>> second_coords;
            for (auto [i, j] : x_coords) {
                int ni = i + dy;
                int nj = j + dx;
                if (ni < 0 || ni >= n || nj < 0 || nj >= m) continue;
                second_coords.insert({ni, nj});
            }
            if (second_coords.size() != total_x) continue;

            set<pair<int, int>> combined;
            for (auto [i, j] : x_coords) {
                combined.insert({i, j});
                combined.insert({i + dy, j + dx});
            }

            int min_r = min(min_element(x_coords.begin(), x_coords.end(), [](auto a, auto b) { return a.first < b.first; })->first,
                           min_element(second_coords.begin(), second_coords.end(), [](auto a, auto b) { return a.first < b.first; })->first);
            int max_r = max(max_element(x_coords.begin(), x_coords.end(), [](auto a, auto b) { return a.first < b.first; })->first,
                           max_element(second_coords.begin(), second_coords.end(), [](auto a, auto b) { return a.first < b.first; })->first);
            int min_c = min(min_element(x_coords.begin(), x_coords.end(), [](auto a, auto b) { return a.second < b.second; })->second,
                           min_element(second_coords.begin(), second_coords.end(), [](auto a, auto b) { return a.second < b.second; })->second);
            int max_c = max(max_element(x_coords.begin(), x_coords.end(), [](auto a, auto b) { return a.second < b.second; })->second,
                           max_element(second_coords.begin(), second_coords.end(), [](auto a, auto b) { return a.second < b.second; })->second);

            if (max_r - min_r + 1 == required_height && max_c - min_c + 1 == required_width) {
                possible = true;
                break;
            }
        }
        if (possible) break;
    }

    cout << (possible ? "YES" : "NO");
    return 0;
}

