    int n, q;
    cin >> n >> q;

    vector<int> server_available_time(n + 1, 0); // 1-based indexing
    priority_queue<int, vector<int>, greater<int>> available_servers;

    for (int i = 1; i <= n; ++i) {
        available_servers.push(i);
    }

    map<int, vector<pair<int, int>>> task_by_time;

    for (int i = 0; i < q; ++i) {
        int t, k, d;
        cin >> t >> k >> d;
        task_by_time[t].push_back({k, d});
    }

    for (auto& time_task : task_by_time) {
        int t = time_task.first;
        vector<pair<int, int>> tasks = time_task.second;

        // Free up servers that are no longer busy at time t
        while (!available_servers.empty() && available_servers.top() <= t) {
            int s = available_servers.top();
            available_servers.pop();
            server_available_time[s] = t;
        }

        // Check if there are enough available servers
        int available_count = 0;
        vector<int> used_servers;
        while (!available_servers.empty() && available_servers.top() <= t) {
            int s = available_servers.top();
            available_servers.pop();
            used_servers.push_back(s);
            ++available_count;
        }

        // Re-add servers that are available after this task
        for (int i = 0; i < min(available_count, (int)tasks.size()); ++i) {
            int s = used_servers[i];
            server_available_time[s] = t + tasks[i].second;
            available_servers.push(s);
