vector<int> lcis(const vector<int>& A, const vector<int>& B) {
    int n = A.size(), m = B.size();
    vector<vector<int>> dp(n + 1, vector<int>(m + 1, 0));
    vector<vector<int>> prev(n + 1, vector<int>(m + 1, -1));

    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= m; ++j) {
            if (A[i - 1] == B[j - 1]) {
                int maxLen = 0, maxIdx = -1;
                for (int k = 0; k < j; ++k) {
                    if (B[k] < B[j - 1] && dp[i][k] > maxLen) {
                        maxLen = dp[i][k];
                        maxIdx = k;
                    }
                }
                dp[i][j] = maxLen + 1;
                prev[i][j] = maxIdx;
            } else if (A[i - 1] < B[j - 1]) {
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1]);
                prev[i][j] = (dp[i][j] == dp[i - 1][j]) ? prev[i - 1][j] : prev[i][j - 1];
            } else {
                dp[i][j] = dp[i][j - 1];
                prev[i][j] = prev[i][j - 1];
