            for (auto& res : item.second.residents) {
                if (res.second > 0) totalAtk += res.second;
            }
            if (totalAtk > maxWeaponAtk) {
                maxWeaponAtk = totalAtk;
                bestWeaponName = item.first;
            }
        }
    }

