    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            cin >> grid[i][j];
        }
    }

    // Directions for adjacent cells (up, down, left, right)
    int dx[] = { -1, 1, 0, 0 };
    int dy[] = { 0, 0, -1, 1 };

    // To store positions of pigs that can be eaten
    set<pair<int, int>> pigs;

    // Find all pigs and mark those adjacent to wolves
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            if (grid[i][j] == 'P') {
                pigs.insert({i, j});
            }
        }
    }

    // To store positions of wolves
    queue<pair<int, int>> wolves;

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            if (grid[i][j] == 'W') {
                wolves.push({i, j});
            }
        }
    }

    // For each wolf, check adjacent pigs and mark them as eaten
    vector<vector<bool>> eaten(n, vector<bool>(m, false));
    int count = 0;
    while (!wolves.empty()) {
        auto [x, y] = wolves.front();
        wolves.pop();

