            int nx = x + dx[i];
            int ny = y + dy[i];
            if (nx >= 0 && nx < n && ny >= 0 && ny < m && grid[nx][ny] == 'P' && !eaten[nx][ny]) {
                eaten[nx][ny] = true;
                count++;
