string findKthSubstring(string s, int k) {
    priority_queue<string, vector<string>, greater<string>> min_heap;
    for (int i = 0; i < s.length(); ++i) {
        min_heap.push(string(1, s[i]));
    }

    while (k-- > 1) {
        string current = min_heap.top();
        min_heap.pop();
        for (int i = 1; i < current.length(); ++i) {
            min_heap.push(current.substr(i));
        }
    }

    return k == 0 ? min_heap.top() : "No such line.";
}

