using namespace std;

int main() {
    int n;
    cin >> n;
    vector<int> a(n);
    for (int i = 0; i < n; ++i) cin >> a[i];

    map<int, int> count;
    for (int num : a) count[num]++;

    unordered_map<int, int> diff_count;
    for (int i = 0; i < n - 1; ++i) {
        int diff = abs(a[i] - a[i + 1]);
        diff_count[diff]++;
    }

    if (n == 2) {
        cout << "YES" << endl;
        return 0;
    }

    int max_freq = 0;
    int max_num = 0;
    for (auto& [num, cnt] : count) {
        if (cnt > max_freq) {
            max_freq = cnt;
            max_num = num;
        }
    }

    if (max_freq > (n + 1) / 2) {
        cout << "NO" << endl;
        return 0;
    }

    int diff = abs(max_num - a[0]);
    if (diff_count[diff] != 1) {
        cout << "NO" << endl;
        return 0;
    }

    int current = max_num;
    int prev = a[0];
    int steps = 1;
    while (steps < n) {
        int next = current + (prev - current) * (-1);
        if (diff_count[abs(current - next)] != 1) {
            cout << "NO" << endl;
            return 0;
        }
        prev = current;
        current = next;
        steps++;
    }

    cout << "YES" << endl;
    return 0;
}

