using namespace std;

int main() {
    string s;
    cin >> s;
    vector<char> cards(s.begin(), s.end());
    set<string> outcomes;

    for (int i = 0; i < (int)s.size(); ++i) {
        if (cards[i] == '?') {
            cards[i] = '0';
            dfs(cards, 0, 0, outcomes);
            cards[i] = '1';
            dfs(cards, 0, 0, outcomes);
            cards[i] = '?';
        }
    }

    for (const auto& out : outcomes) {
        cout << out << endl;
    }

    return 0;
}

void dfs(vector<char>& cards, int turn, int removed, set<string>& outcomes) {
    if (removed == cards.size() - 2) {
        string res;
        for (int i = 0; i < cards.size(); ++i) {
            if (i != 0 && i != cards.size() - 1) continue;
            res += cards[i];
        }
        outcomes.insert(res);
        return;
    }

    if (turn % 2 == 0) { // Masha's turn, wants to minimize
        for (int i = 0; i < cards.size(); ++i) {
            if (cards[i] == '?') {
                cards[i] = '0';
                dfs(cards, turn + 1, removed + 1, outcomes);
                cards[i] = '?';
            }
        }
    } else { // Petya's turn, wants to maximize
        for (int i = 0; i < cards.size(); ++i) {
            if (cards[i] == '?') {
                cards[i] = '1';
                dfs(cards, turn + 1, removed + 1, outcomes);
                cards[i] = '?';
            }
        }
    }
}

