    for (long long i = 0; i < t; ++i) {
        cin >> p[i];
    }
    long long K = 0;
    for (auto& f : figures) {
        K += f.first;
    }
    vector<long long> factor_slots(t + 1, 0);
    long long prev_total = 0;
    long long remaining = K;
    for (long long i = 0; i < t; ++i) {
        long long delta = p[i] - prev_total;
        long long s = min(delta, remaining);
        factor_slots[i] = s;
        remaining -= s;
        prev_total += s;
    }
    factor_slots[t] = remaining;

    long long total = 0;
    for (long long i = t; i >= 0; --i) {
        if (factor_slots[i] == 0) continue;
        long long factor = i + 1;
        long long slot_count = factor_slots[i];
        for (long long j = 0; j < n && slot_count > 0; ++j) {
            if (figures[j].first == 0) continue;
            long long take = min(figures[j].first, slot_count);
            total += take * factor * figures[j].second;
            figures[j].first -= take;
            slot_count -= take;
        }
    }
