#include <iostream>
#include <vector>
#include <cmath>
using namespace std;

long long maxResult(int n) {
    vector<long long> dp(n + 1, 0);
    dp[1] = 1;
    for (int i = 2; i <= n; ++i) {
        long long max_sum = 0;
        for (int j = 2; j <= sqrt(i); ++j) {
            if (i % j == 0) {
                long long a = j;
                long long b = i / j;
                max_sum = max(max_sum, dp[a] + dp[b] + i);
            }
        }
        dp[i] = max_sum;
    }
    return dp[n];
}

int main() {
    int n;
    cin >> n;
    cout << maxResult(n) << endl;
    return 0;
}

