#include <cmath>

using namespace std;

unordered_map<long long, long long> memo;

long long smallest_divisor(long long m) {
    if (m % 2 == 0) return 2;
    for (long long i = 3; i * i <= m; i += 2) {
        if (m % i == 0) {
            return i;
        }
    }
    return m;
}

long long compute_sum(long long m) {
    if (m == 1) return 1;
    if (memo.find(m) != memo.end()) {
        return memo[m];
    }
    long long a = smallest_divisor(m);
    long long b = m / a;
    memo[m] = m + compute_sum(b);
    return memo[m];
}

int main() {
    long long n;
    cin >> n;
    memo.clear();
    cout << compute_sum(n) << endl;
    return 0;
}

