#include <iostream>
#include <vector>
using namespace std;

int main() {
    int k;
    cin >> k;

    int n = 100;
    vector<vector<int>> adj(n, vector<int>(n, 0));

    // Create a complete graph on the first m vertices where m is such that m*(m-1)*(m-2)/6 >= k
    int m = 3;
    while (m * (m - 1) * (m - 2) / 6 < k) m++;

    // Add edges between first m vertices to form a complete graph
    for (int i = 0; i < m; i++) {
        for (int j = i + 1; j < m; j++) {
            adj[i][j] = adj[j][i] = 1;
        }
    }

    // Subtract the extra cycles by removing edges from the complete graph
    int total = m * (m - 1) * (m - 2) / 6;
    int extra = total - k;

    // Start removing edges from the last possible ones
    for (int i = m - 2; i >= 0; i--) {
        for (int j = i + 1; j < m; j++) {
            if (extra == 0) break;
            adj[i][j] = adj[j][i] = 0;
            extra--;
        }
    }

    // Print the adjacency matrix
    cout << n << endl;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            cout << adj[i][j];
        }
        cout << endl;
    }

    return 0;
}

