#include <iostream>
#include <vector>
using namespace std;

int main() {
    int k;
    cin >> k;

    // We will construct a complete graph of size m where m(m-1)(m-2)/6 >= k
    int m = 3;
    while (m * (m - 1) * (m - 2) / 6 < k) m++;

    // We need to remove some edges from the complete graph to get exactly k triangles
    int n = m;
    vector<vector<char>> adj(n, vector<char>(n, '0'));

    // Create a complete graph
    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            adj[i][j] = '1';
            adj[j][i] = '1';
        }
    }

    // Calculate how many edges to remove to get exactly k triangles
    int complete_tris = m * (m - 1) * (m - 2) / 6;
    int remove = complete_tris - k;

    // Remove edges one by one to reduce the number of triangles
    int edges_removed = 0;
    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            if (edges_removed >= remove) break;
            if (adj[i][j] == '1') {
                adj[i][j] = '0';
                adj[j][i] = '0';
                edges_removed++;
            }
        }
    }

    // Output the result
    cout << n << endl;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            cout << adj[i][j];
        }
        cout << endl;
    }
    return 0;
}

