vector<int> applyPermutation(const vector<int>& p, const vector<int>& q) {
    vector<int> result(p.size());
    for (int i = 0; i < p.size(); ++i) {
        result[i] = p[q[i] - 1];
    }
    return result;
}

vector<int> applyInversePermutation(const vector<int>& p, const vector<int>& q) {
    vector<int> invQ(p.size());
    for (int i = 0; i < q.size(); ++i) {
        invQ[q[i] - 1] = i + 1;
    }
    vector<int> result(p.size());
    for (int i = 0; i < p.size(); ++i) {
        result[invQ[i] - 1] = p[i];
    }
    return result;
}

