    sort(angles.begin(), angles.end());

    // Find the minimum angle between adjacent points
    double min_angle = 360.0;
    for (int i = 0; i < n; ++i) {
        double diff = angles[(i + 1) % n] - angles[i];
        min_angle = min(min_angle, diff);
    }

    // The minimum angle between any two points is the minimum of the above
    // but we need to find the angle that covers all points, which is 360 - max_gap
    double max_gap = 0.0;
    for (int i = 0; i < n; ++i) {
        double gap = angles[(i + 1) % n] - angles[i];
        max_gap = max(max_gap, gap);
