#include <iostream>
#include <vector>
#include <cmath>
#include <algorithm>
#include <iomanip>

using namespace std;

struct Point {
    double x, y;
};

double computeAngle(const Point& a, const Point& b) {
    double dot = a.x * b.x + a.y * b.y;
    double normA = sqrt(a.x * a.x + a.y * a.y);
    double normB = sqrt(b.x * b.x + b.y * b.y);
    double cosine = dot / (normA * normB);
    // Clamp cosine to avoid numerical errors
    cosine = max(min(cosine, 1.0), -1.0);
    return acos(cosine) * 180 / M_PI;
}

int main() {
    int n;
    cin >> n;
    vector<Point> points(n);
    for (int i = 0; i < n; ++i) {
        cin >> points[i].x >> points[i].y;
    }

    // Normalize points to be in polar coordinates
    vector<double> angles;
    for (const auto& p : points) {
        if (p.x == 0 && p.y == 0) continue; // Not possible as per problem statement
        double angle = atan2(p.y, p.x);
        // Convert to degrees and make it in [0, 360)
        angle = angle * 180 / M_PI;
        if (angle < 0) angle += 360;
        angles.push_back(angle);
    }

    // Sort angles
    sort(angles.begin(), angles.end());

    // Find minimum angle between two consecutive points
    double minAngle = 360.0;
    for (int i = 0; i < n; ++i) {
        double diff = angles[(i + 1) % n] - angles[i];
        minAngle = min(minAngle, diff);
    }

    // The answer is minAngle or 360 - minAngle, whichever is smaller
    minAngle = min(minAngle, 360.0 - minAngle);

    cout << fixed << setprecision(10) << minAngle << endl;
    return 0;
}

