    for (int i = 0; i < n; ++i) {
        double x1 = points[i].first;
        double y1 = points[i].second;
        double ang1 = atan2(y1, x1) * 180 / M_PI;
        double ang2 = atan2(y1, -x1) * 180 / M_PI;
