        double ang4 = atan2(-y1, -x1) * 180 / M_PI;

        double angle = 0;
        if (ang1 < 0) ang1 += 360;
        if (ang2 < 0) ang2 += 360;
        if (ang3 < 0) ang3 += 360;
        if (ang4 < 0) ang4 += 360;

