using namespace std;

double probability(int n, int m, int k) {
    if (m > n + k) return 0.0;
    long long total = 1;
    for (int i = 1; i <= n + m; ++i) total *= i;
    long long favorable = 0;
    for (int i = 0; i <= m; ++i) {
        if (i > n) break;
        vector<long long> comb(n + m - i, 1);
        for (int j = 1; j < i; ++j) comb[j] = comb[j-1] * (n + m - i - j + 1) / j;
        favorable += comb[i];
    }
    return static_cast<double>(favorable) / static_cast<double>(total);
}

int main() {
    int n, m, k;
    cin >> n >> m >> k;
    cout << fixed << setprecision(6) << probability(n, m, k) << endl;
    return 0;
}

