using namespace std;

int main() {
    int n, m;
    cin >> n >> m;
    vector<pair<int, double>> plants(n);
    for (int i = 0; i < n; ++i) {
        cin >> plants[i].first >> plants[i].second;
    }

    // Sort plants by species
    sort(plants.begin(), plants.end(), [](const pair<int, double>& a, const pair<int, double>& b) {
        return a.first < b.first;
    });

    // Now find the number of plants that are already in the correct order
    // We need to find the length of the longest non-decreasing subsequence of species
    // because the rest will need to be replanted
    vector<int> dp(m + 1, 1);
    for (int i = 1; i < n; ++i) {
        for (int j = 0; j < i; ++j) {
            if (plants[j].first <= plants[i].first) {
                dp[plants[i].first] = max(dp[plants[i].first], dp[plants[j].first] + 1);
            }
        }
    }

    // The answer is n minus the length of the longest non-decreasing subsequence
    int max_len = 0;
    for (int i = 1; i <= m; ++i) {
        max_len = max(max_len, dp[i]);
    }
    cout << n - max_len << endl;
    return 0;
}

