#include <iostream>
#include <vector>
#include <algorithm>
#include <iomanip>
#include <sstream>

using namespace std;

int main() {
    int n, m;
    cin >> n >> m;

    vector<pair<int, double>> plants;
    for (int i = 0; i < n; ++i) {
        int s;
        double x;
        cin >> s >> x;
        plants.push_back({s, x});
    }

    // We need to find the maximum number of plants that can be kept in order
    // such that all plants of species 1 come before species 2, etc.
    // This is equivalent to finding the length of the longest non-decreasing subsequence
    // where the species number is the key.

    vector<int> dp(m + 1, 0);
    int max_len = 0;

    for (auto& p : plants) {
        int s = p.first;
        // Find the first position in dp where dp[i] >= s, and replace it with s
        // This is the standard algorithm for LIS (Longest Increasing Subsequence)
        int l = 0, r = max_len;
        while (l < r) {
            int mid = (l + r) / 2;
            if (dp[mid] < s) l = mid + 1;
            else r = mid;
        }
        if (l == max_len) {
            dp.push_back(s);
            max_len++;
        } else {
            dp[l] = s;
        }
    }

    cout << n - max_len << endl;
    return 0;
}

