        cout << 0;
        return 0;
    }

    int turns = 0;
    int dx = 1, dy = 0;  // initial direction (right)
    int length = 1;
    int steps = 0;

    while (true) {
        // Move in current direction
        for (int i = 0; i < length; ++i) {
            if (x == 0 && y == 0) break;
            if (x == 0 && y == 0) break;
            steps++;
            if (steps == 1) {
                if (x == 0 && y == 0) break;
                if (x == 0 && y == 0) break;
                if (x == 0 && y == 0) break;
            }
            if (x == 0 && y == 0) break;
            if (x == 0 && y == 0) break;
            if (x == 0 && y == 0) break;
        }
        if (x == 0 && y == 0) break;
        if (x == 0 && y == 0) break;
        if (x == 0 && y == 0) break;
        // Turn right
        turns++;
        // Change direction
        int temp = dx;
        dx = -dy;
        dy = temp;
    }

