    int p;
    cin >> p;
    vector<int> phi(p - 1);
    for (int i = 1; i < p; ++i) phi[i - 1] = i;
    for (int i = 2; i < p; ++i) {
        if (p % i == 0) {
            int cnt = 0;
            for (int j = 0; j < p - 1; ++j) {
                if (gcd(i, phi[j]) == 1) ++cnt;
            }
            if (cnt > 0) {
                int k = 0;
                for (int j = 1; j < p; ++j) {
                    if (pow_mod(i, j, p) == 1) ++k;
                }
                if (k == p - 1) {
                    cout << i << endl;
                }
            }
        }
    }
    return 0;
}

int pow_mod(int base, int exp, int mod) {
    int result = 1;
    base = base % mod;
    while (exp > 0) {
        if (exp % 2 == 1) {
            result = (result * base) % mod;
        }
        base = (base * base) % mod;
        exp = exp / 2;
    }
    return result;
}

int gcd(int a, int b) {
    while (b != 0) {
        int temp = b;
        b = a % b;
        a = temp;
    }
    return a;
}

