    for (int i = 0; i < n; ++i) {
        int u, v;
        cin >> u >> v;
        stamps[i] = {u, v};
        graph[u].insert(v);
        graph[v].insert(u);
    }

    // Find start node with only one neighbor
    int start;
    for (auto& [u, neighbors] : graph) {
        if (neighbors.size() == 1) {
            start = u;
            break;
        }
    }

    // Build adjacency list for traversal
    unordered_map<int, vector<int>> adj;
    for (const auto& [u, v] : stamps) {
        adj[u].push_back(v);
        adj[v].push_back(u);
    }

    vector<int> path;
    unordered_set<int> visited;
    queue<int> q;
    q.push(start);
    visited.insert(start);

    while (!q.empty()) {
        int u = q.front();
        q.pop();
        path.push_back(u);
        for (int v : adj[u]) {
            if (visited.find(v) == visited.end()) {
                visited.insert(v);
                q.push(v);
            }
        }
