    while (!s.empty()) {
        int u = s.top();
        path.push_back(u);
        s.pop();

        // Find the next city to visit (the only unvisited neighbor)
        int next = -1;
        for (int v : graph[u]) {
            if (!visited[v]) {
                next = v;
                break;
            }
        }

        if (next != -1) {
            visited[next] = true;
            s.push(next);
        }
    }

    // Output the path
    for (int i = 0; i < path.size(); ++i) {
        cout << path[i];
        if (i != path.size() - 1) cout << " ";
