using namespace std;

int main() {
    int n;
    cin >> n;
    unordered_map<int, int> graph;
    unordered_map<int, bool> visited;
    vector<int> path;

    for (int i = 0; i < n; ++i) {
        int u, v;
        cin >> u >> v;
        graph[u] = v;
        graph[v] = u;
    }

    stack<int> dfs;
    dfs.push(1);
    visited[1] = true;
    int prev = -1;

    while (!dfs.empty()) {
        int u = dfs.top();
        dfs.pop();
        path.push_back(u);
        if (graph.find(u) != graph.end() && !visited[graph[u]]) {
            dfs.push(graph[u]);
            visited[graph[u]] = true;
            prev = u;
        }
    }

    // Find the starting point of the path
    int start;
    for (int i = 0; i < path.size(); ++i) {
        if (graph.find(path[i]) != graph.end() && graph[path[i]] == path[i - 1]) {
            start = i;
            break;
        }
    }

    // Reverse the path from start to end to get the correct order
    vector<int> result;
    for (int i = start; i < path.size(); ++i) {
        result.push_back(path[i]);
    }
    for (int i = result.size() - 1; i >= 0; --i) {
        result.push_back(result[i]);
    }

    // Remove duplicates and adjust the path to have n+1 elements
    vector<int> finalResult;
    for (int i = 0; i < result.size(); ++i) {
        if (i == 0 || result[i] != result[i - 1]) {
            finalResult.push_back(result[i]);
        }
    }

    for (int i = 0; i < finalResult.size(); ++i) {
        cout << finalResult[i] << " ";
    }

    return 0;
}

