#include <string>
#include <vector>
using namespace std;

int main() {
    string s, t;
    cin >> s >> t;
    int dx = t[0] - s[0];
    int dy = t[1] - s[1];
    int n = max(abs(dx), abs(dy));
    vector<string> moves;
    for (int i = 0; i < n; ++i) {
        if (dx > 0) moves.push_back("R");
        else if (dx < 0) moves.push_back("L");
        else moves.push_back("D");
        if (dy > 0) moves.push_back("D");
        else if (dy < 0) moves.push_back("U");
        else moves.push_back("R");
        dx -= (dx > 0 ? 1 : dx < 0 ? -1 : 0);
        dy -= (dy > 0 ? 1 : dy < 0 ? -1 : 0);
    }
    cout << moves.size() << endl;
    for (auto& move : moves) {
        cout << move << endl;
    }
    return 0;
}

