bool isValidEmail(string s) {
    int atCount = 0;
    for (char c : s) {
        if (c == '@') {
            atCount++;
        }
    }
    if (atCount != 1) return false;
    int firstAt = s.find('@');
    if (firstAt == string::npos) return false;
    if (firstAt == 0 || firstAt == s.length() - 1) return false;
    return true;
}

string solve(string s) {
    vector<string> result;
    string current;
    int atCount = 0;
    int prevAt = -1;

    for (int i = 0; i < s.length(); i++) {
        if (s[i] == '@') {
            atCount++;
            prevAt = i;
        }
        if (atCount > 2) break;
        current += s[i];
    }

    if (atCount != 2) return "No solution";

    int firstAt = current.find('@');
    int secondAt = current.rfind('@');

    if (firstAt == string::npos || secondAt == string::npos || firstAt == secondAt) return "No solution";
    if (firstAt == 0 || secondAt == current.length() - 1) return "No solution";

    string a = current.substr(0, firstAt);
    string b = current.substr(firstAt + 1, secondAt - firstAt - 1);
    string c = current.substr(secondAt + 1);

    if (a.empty() || b.empty() || c.empty()) return "No solution";

    if (isValidEmail(a) && isValidEmail(b) && isValidEmail(c)) {
        result.push_back(a);
        result.push_back(b);
        result.push_back(c);
    }

