bool isValidEmail(const string& s) {
    int at = -1;
    for (int i = 0; i < s.size(); ++i) {
        if (s[i] == '@') {
            at = i;
        }
    }
    if (at == -1 || at == 0 || at == s.size() - 1) {
        return false;
    }
    return true;
}

vector<string> splitEmails(const string& s) {
    vector<string> result;
    string current;
    for (char c : s) {
        current += c;
        if (c == '@') {
            int lastAt = current.find_last_of('@');
            if (lastAt != current.size() - 1 && isValidEmail(current)) {
                result.push_back(current);
                current.clear();
            }
        }
    }
    if (!current.empty() && isValidEmail(current)) {
        result.push_back(current);
    }
    return result;
}

