#include <iostream>
#include <cmath>
using namespace std;

long long count_squares(int n, int m, int x) {
    long long res = 0;
    if (x == 1) {
        res = (long long)(n * m + 1) / 2;
    } else {
        int k = x - 1;
        int a = min(n, m);
        int b = max(n, m);
        int t = (a - 1) / 2;
        if (k <= t) {
            res = 4 * (long long)k * (k + 1);
        } else {
            long long total = 4 * (long long)t * (t + 1);
            int r = k - t;
            int s = min(b - 2 * t, a - 2 * t);
            res = total + 4 * (long long)r * s;
        }
    }
    return res;
}

int main() {
    int n, m, x;
    cin >> n >> m >> x;
    cout << count_squares(n, m, x) << endl;
    return 0;
}

