#include <iostream>
#include <vector>
#include <queue>
#include <unordered_map>
#include <algorithm>
using namespace std;

struct State {
    vector<int> nums;
    string path;
};

bool isAllOne(const vector<int>& nums) {
    for (int n : nums) {
        if (n != 1) return false;
    }
    return true;
}

bool canDivide(const vector<int>& nums, int pos) {
    if (pos == 0) return nums[0] % 2 == 0 && nums[1] % 2 == 0;
    if (pos == 1) return nums[1] % 2 == 0 && nums[2] % 2 == 0;
    if (pos == 2) return nums[2] % 2 == 0 && nums[3] % 2 == 0;
    if (pos == 3) return nums[3] % 2 == 0 && nums[0] % 2 == 0;
    return false;
}

void divide(vector<int>& nums, int pos) {
    if (pos == 0) {
        nums[0] /= 2;
        nums[1] /= 2;
    } else if (pos == 1) {
        nums[1] /= 2;
        nums[2] /= 2;
    } else if (pos == 2) {
        nums[2] /= 2;
        nums[3] /= 2;
    } else if (pos == 3) {
        nums[3] /= 2;
        nums[0] /= 2;
    }
}

void add(vector<int>& nums, int pos) {
    if (pos == 0) {
        nums[0]++;
        nums[1]++;
    } else if (pos == 1) {
        nums[1]++;
        nums[2]++;
    } else if (pos == 2) {
        nums[2]++;
        nums[3]++;
    } else if (pos == 3) {
        nums[3]++;
        nums[0]++;
    }
}

vector<string> bfs(const vector<int>& initial) {
    queue<State> q;
    unordered_map<string, bool> visited;
    q.push({initial, ""});
    visited[to_string(initial[0]) + " " + to_string(initial[1]) + " " + to_string(initial[2]) + " " + to_string(initial[3])} = true;

    while (!q.empty()) {
        State current = q.front();
        q.pop();

        if (isAllOne(current.nums)) {
            return {current.path};
        }

        for (int i = 0; i < 4; ++i) {
            if (canDivide(current.nums, i)) {
                vector<int> next = current.nums;
                divide(next, i);
                string key = to_string(next[0]) + " " + to_string(next[1]) + " " + to_string(next[2]) + " " + to_string(next[3]);
                if (!visited[key]) {
                    visited[key] = true;
                    q.push({next, current.path + "/"+to_string(i+1)});
                }
            }

            if (current.nums[i] != 1) {
                vector<int> next = current.nums;
                add(next, i);
                string key = to_string(next[0]) + " " + to_string(next[1]) + " " + to_string(next[2]) + " " + to_string(next[3]);
                if (!visited[key]) {
                    visited[key] = true;
                    q.push({next, current.path + "+"+to_string(i+1)});
                }
            }
        }
    }

    return {-1};
}

