        }
        new_nums[pos - 1] /= 2;
        new_nums[pos] /= 2;
    }
    return new_nums;
}

vector<int> get_next_states(const vector<int>& nums) {
    vector<int> next_states;
    // Check for '+' operations
    for (int i = 1; i <= 4; ++i) {
        vector<int> new_nums = nums;
        new_nums[i - 1]++;
        new_nums[i % 4]++;
        next_states.push_back(i);
    }
    // Check for '/' operations
    for (int i = 1; i <= 4; ++i) {
        vector<int> new_nums = nums;
        if (new_nums[i - 1] % 2 == 0 && new_nums[i % 4] % 2 == 0) {
            new_nums[i - 1] /= 2;
            new_nums[i % 4] /= 2;
