#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

vector<string> operations;

void solve(int a, int b, int c, int d) {
    while (a != 1 || b != 1 || c != 1 || d != 1) {
        bool found = false;
        // Try to divide if possible
        if (a % 2 == 0 && b % 2 == 0) {
            a /= 2;
            b /= 2;
            operations.push_back("/1");
            found = true;
        } else if (b % 2 == 0 && c % 2 == 0) {
            b /= 2;
            c /= 2;
            operations.push_back("/2");
            found = true;
        } else if (c % 2 == 0 && d % 2 == 0) {
            c /= 2;
            d /= 2;
            operations.push_back("/3");
            found = true;
        } else if (d % 2 == 0 && a % 2 == 0) {
            d /= 2;
            a /= 2;
            operations.push_back("/4");
            found = true;
        }
        if (!found) {
            // Try to add if possible
            if (a + 1 == b || b + 1 == a) {
                if (a + 1 == b) {
                    a++;
                    operations.push_back("+1");
                } else {
                    b++;
                    operations.push_back("+2");
                }
            } else if (b + 1 == c || c + 1 == b) {
                if (b + 1 == c) {
                    b++;
                    operations.push_back("+2");
                } else {
                    c++;
                    operations.push_back("+3");
                }
            } else if (c + 1 == d || d + 1 == c) {
                if (c + 1 == d) {
                    c++;
                    operations.push_back("+3");
                } else {
                    d++;
                    operations.push_back("+4");
                }
            } else if (d + 1 == a || a + 1 == d) {
                if (d + 1 == a) {
                    d++;
                    operations.push_back("+4");
                } else {
                    a++;
                    operations.push_back("+1");
                }
            } else {
                cout << "-1" << endl;
                return;
            }
        }
    }
}

