double max_equal_energy(int n, int k, vector<double>& a) {
    double left = 0.0, right = 1e6;
    for (int i = 0; i < 100; ++i) {
        double mid = (left + right) / 2;
        double total = 0.0;
        for (double val : a) {
            if (val < mid) {
                total += (mid - val) * 100.0 / (100.0 - k);
