        int v = q[0] - 'A';
        likes[u][v]++;
    }
    int a, b, c;
    cin >> a >> b >> c;

    int min_diff = INT_MAX;
    int max_likes = 0;

    // All possible ways to split 7 heroes into 3 teams
    // We will use bitmask approach for all possible team assignments
    for (int mask1 = 0; mask1 < (1 << 7); ++mask1) {
        for (int mask2 = mask1 + 1; mask2 < (1 << 7); ++mask2) {
            if ((mask1 & mask2) != 0) continue;
            // mask1 and mask2 represent two teams, mask3 is the third
            int mask3 = ((1 << 7) - 1) ^ (mask1 | mask2);
            if (mask3 == 0) continue; // third team can't be empty

            vector<int> team_sizes(3, 0);
            for (int i = 0; i < 7; ++i) {
                if (mask1 & (1 << i)) team_sizes[0]++;
                else if (mask2 & (1 << i)) team_sizes[1]++;
                else team_sizes[2]++;
            }

            int exp1 = a / team_sizes[0];
            int exp2 = b / team_sizes[1];
            int exp3 = c / team_sizes[2];

            int current_diff = max(exp1, max(exp2, exp3)) - min(exp1, min(exp2, exp3));
            if (current_diff < min_diff) {
                min_diff = current_diff;
                max_likes = 0;
