#include <iostream>
#include <vector>
#include <string>
#include <cmath>

using namespace std;

string find_kth_string(int n, long long k) {
    vector<string> all_strings;
    for (int i = 0; i < (1 << n); ++i) {
        string s(n, '0');
        for (int j = 0; j < n; ++j) {
            if (i & (1 << j)) s[j] = '1';
        }
        all_strings.push_back(s);
    }

    vector<string> unique_heaps;
    vector<bool> seen(1 << n, false);
    for (auto& s : all_strings) {
        bool is_unique = true;
        for (int i = 0; i < n; ++i) {
            if (s[i] == '1') {
                string s1 = s;
                string s2 = s;
                for (int j = 0; j < n; ++j) {
                    s1[j] = '0' + (s1[j] == '1');
                    s2[j] = '0' + (s2[j] == '0');
                }
                for (int j = 0; j < n; ++j) {
                    string rotated_s = s.substr(j) + s.substr(0, j);
                    if ((rotated_s == s1) || (rotated_s == s2)) {
                        is_unique = false;
                        break;
                    }
                }
                if (!is_unique) break;
            }
        }
        if (is_unique) {
            unique_heaps.push_back(s);
        }
    }

    sort(unique_heaps.begin(), unique_heaps.end(), [](string a, string b) {
        for (int i = 0; i < a.length(); ++i) {
            if (a[i] != b[i]) {
                return a[i] < b[i];
            }
        }
        return false;
    });

    if (k > unique_heaps.size()) return "-1";
    return unique_heaps[k - 1];
}

int main() {
    int n;
    long long k;
    cin >> n >> k;
    cout << find_kth_string(n, k) << endl;
    return 0;
}

