#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

long long reflect(long long n) {
    long long res = 0;
    long long power = 1;
    while (n > 0) {
        res += power * (9 - (n % 10));
        n /= 10;
        power *= 10;
    }
    return res;
}

long long weight(long long n) {
    return n * reflect(n);
}

long long maxWeight(int l, int r) {
    long long maxW = 0;
    for (long long i = l; i <= r; ++i) {
        maxW = max(maxW, weight(i));
    }
    return maxW;
}

int main() {
    int l, r;
    cin >> l >> r;
    cout << maxWeight(l, r) << endl;
    return 0;
}

