#include <iostream>
#include <vector>
#include <algorithm>
#include <string>

long long reflect(long long n) {
    std::string s = std::to_string(n);
    std::string reflected;
    for (char c : s) {
        reflected += '9' - (c - '0');
    }
    return std::stoll(reflected);
}

long long weight(long long n) {
    return n * reflect(n);
}

long long max_weight_in_range(long long l, long long r) {
    long long max_weight = 0;
    for (long long n = l; n <= r; ++n) {
        long long w = weight(n);
        if (w > max_weight) {
            max_weight = w;
        }
    }
    return max_weight;
}

int main() {
    long long l, r;
    std::cin >> l >> r;
    std::cout << max_weight_in_range(l, r) << std::endl;
    return 0;
}

