#include <cmath>
using namespace std;

long long reflection(long long n) {
    long long res = 0, pow10 = 1;
    while (n > 0) {
        res += (9 - (n % 10)) * pow10;
        pow10 *= 10;
        n /= 10;
    }
    return res;
}

long long weight(long long n) {
    return n * reflection(n);
}

long long maxWeightInRange(long long l, long long r) {
    long long maxW = 0;
    for (long long i = l; i <= r; ++i) {
        long long w = weight(i);
        if (w > maxW) maxW = w;
    }
    return maxW;
}

int main() {
    long long l, r;
    cin >> l >> r;
    cout << maxWeightInRange(l, r) << endl;
    return 0;
}

