#include <vector>
#include <algorithm>
#include <cmath>

using namespace std;

long long reflect(long long n) {
    string s = to_string(n);
    string r;
    for (char c : s) {
        r += '9' - (c - '0');
    }
    return stoll(r);
}

long long weight(long long n) {
    return n * reflect(n);
}

long long maxWeight(int l, int r) {
    long long maxW = 0;
    for (int i = l; i <= r; ++i) {
        maxW = max(maxW, weight(i));
    }
    return maxW;
}

