#include <vector>
#include <cmath>
using namespace std;

long long fact(int n) {
    long long res = 1;
    for (int i = 2; i <= n; ++i) res *= i;
    return res;
}

long long comb(int n, int k) {
    if (k > n) return 0;
    if (k == 0 || k == n) return 1;
    k = min(k, n - k);
    long long res = 1;
    for (int i = 1; i <= k; ++i) res *= (n - i + 1) / i;
    return res;
}

int main() {
    string s;
    cin >> s;
    map<char, int> colorCount;
    for (char c : s) colorCount[c]++;

    long long total = fact(6);
    for (auto& [c, cnt] : colorCount) {
        total /= fact(cnt);
    }

    // Number of distinct cube orientations: 24
    // Using Burnside's lemma, count distinct colorings up to rotation

    // For each type of rotation, count the number of colorings fixed by that rotation
    // Then divide by the number of rotations (24)

    // Identity rotation: fixes all colorings
    long long fixed = total;

    // 90-degree and 270-degree rotations: only possible if all 4 sides are same color
    int count90 = 0;
    for (auto& [c, cnt] : colorCount) {
        if (cnt == 4) count90++;
    }
    fixed += count90 * fact(2); // 2 rotations (90 and 270) with 2 remaining positions

    // 180-degree rotations: pairs of opposite faces must have same color
    int count180 = 0;
    for (auto& [c, cnt] : colorCount) {
        if (cnt % 2 == 0) count180++;
    }
    fixed += comb(count180, 3) * fact(1); // choose 3 pairs, each pair same color

    // 120-degree and 240-degree rotations: only possible if all 3 faces are same color
    int count120 = 0;
    for (auto& [c, cnt] : colorCount) {
        if (cnt == 3) count120++;
    }
    fixed += count120 * fact(1); // 2 rotations (120 and 240) with 3 remaining positions

    // 6 rotations (axis through face centers): for each axis, if 3 faces are same color, 2 rotations
    // but we already considered 120 and 240-degree rotations for that case
    // So for each axis, check if 2 pairs of opposite faces have same color
    // For each such axis, 2 rotations (clockwise and counterclockwise)
    int countAxis = 0;
    for (auto& [c, cnt] : colorCount) {
        if (cnt % 2 == 0) countAxis++;
    }
    fixed += comb(countAxis, 3) * fact(1) * 2; // 3 axes, 2 rotations each

    // 6 rotations (axis through edges): 2 pairs of opposite faces must be same color
    int countEdge = 0;
    for (auto& [c, cnt] : colorCount) {
        if (cnt >= 2) countEdge++;
    }
    fixed += comb(countEdge, 3) * fact(1) * 2; // 3 axes, 2 rotations each

    // Final answer
    long long answer = fixed / 24;
    cout << answer << endl;
    return 0;
}

