using namespace std;

int main() {
    int n;
    cin >> n;
    vector<tuple<int, int, int>> rings(n);
    for (int i = 0; i < n; ++i) {
        int a, b, h;
        cin >> a >> b >> h;
        rings[i] = {a, b, h};
    }

    // Sort rings by outer radius in decreasing order
    sort(rings.begin(), rings.end(), [](const tuple<int, int, int>& x, const tuple<int, int, int>& y) {
        return get<1>(x) > get<1>(y);
    });

    // Use a priority queue (min-heap) to keep track of the best possible heights
    priority_queue<int> pq;
    long long max_height = 0;

    for (const auto& ring : rings) {
        int a = get<0>(ring);
        int b = get<1>(ring);
        int h = get<2>(ring);

        // If current ring's inner radius is greater than the smallest outer radius in the heap
        // Then it can't be placed on top of any existing ring, so we start a new stack
        if (!pq.empty() && a > pq.top()) {
            max_height += h;
            pq.push(b);
        } else {
            // Otherwise, we check if we can replace a smaller height with a larger one
            if (pq.empty() || h > pq.top()) {
                max_height += h;
                pq.push(b);
                // If the current ring's outer radius is smaller than the smallest in the heap, we pop it
                while (!pq.empty() && b < pq.top()) {
                    max_height -= pq.top();
                    pq.pop();
                }
            }
        }
    }

    cout << max_height << endl;
    return 0;
}

