#include <numeric>

using namespace std;

double poisson_prob(int k, int p) {
    if (k < 0) return 0.0;
    double lambda = p;
    double prob = exp(-lambda) * pow(lambda, k) / tgamma(k + 1);
    return prob;
}

double uniform_prob(int k, int p) {
    if (k < 0 || k > 2 * p) return 0.0;
    return 1.0 / (2 * p + 1);
}

int main() {
    int V;
    cin >> V;
    for (int v = 0; v < V; ++v) {
        vector<int> sample(250);
        for (int i = 0; i < 250; ++i) {
            cin >> sample[i];
        }
        double max_poisson = 0.0;
        double max_uniform = 0.0;
        int p = 0;
        for (int i = 0; i < sample.size(); ++i) {
            int k = sample[i];
            if (k >= p) p = k;
        }
        for (int k : sample) {
            double p_poisson = poisson_prob(k, p);
            double p_uniform = uniform_prob(k, p);
            max_poisson = max(max_poisson, p_poisson);
            max_uniform = max(max_uniform, p_uniform);
        }
        if (max_poisson > max_uniform) {
            cout << "poisson" << endl;
        } else {
            cout << "uniform" << endl;
        }
    }
    return 0;
}

