using namespace std;

struct Circle {
    double x, y, r;
};

double area_of_circle(double r) {
    return M_PI * r * r;
}

double area_of_intersection(double r1, double r2, double dx, double dy) {
    double d = sqrt(dx * dx + dy * dy);
    if (d >= r1 + r2) return 0.0;
    if (d <= abs(r1 - r2)) return area_of_circle(min(r1, r2));
    double a = (r1 * r1 + r2 * r2 - d * d) / (2 * r1 * r2);
    double h = r1 * r1 * (1 - a * a) - (r2 * r2 * (1 - (1 - a) * (1 - a))) / (2 * a * (1 - a));
    return 2 * (r1 * r1 * acos((r1 * r1 + d * d - r2 * r2) / (2 * r1 * d)) - 
                d * (r1 * r1 - h * h) / (2 * d));
}

double compute_spaciousness(const vector<Circle>& circles) {
    unordered_set<int> active;
    double total = 0.0;
    for (size_t i = 0; i < circles.size(); ++i) {
        int count = 0;
        for (int j : active) {
            double dx = circles[i].x - circles[j].x;
            double dy = circles[i].y - circles[j].y;
            double d = sqrt(dx * dx + dy * dy);
            if (d <= circles[i].r + circles[j].r &&
                d >= abs(circles[i].r - circles[j].r)) {
                count++;
            }
        }
        if (count % 2 == 1) {
            total += area_of_circle(circles[i].r);
        }
    }
    return total;
}

int main() {
    int n;
