    }

    vector<int> a(n + 1, 0); // a[1..n]
    unordered_map<int, int> used;

    // Initialize a with 1 to n
    for (int i = 1; i <= n; ++i) {
        a[i] = i;
        used[i] = 1;
    }

    // First leader is l[0]
    a[l[0]] = 0;

    for (int i = 1; i < m; ++i) {
        int prev = l[i - 1];
        int next = l[i];
        // Find a number to assign to prev such that it leads to next
        for (int val = 1; val <= n; ++val) {
            if (used[val]) continue;
            int pos = (prev + val - 1) % n;
            if (pos == next - 1) {
                a[prev] = val;
                used[val] = 1;
                break;
            }
        }
    }

    // Check if all values are used
    for (int i = 1; i <= n; ++i) {
        if (!used[i]) {
            cout << -1;
            return 0;
        }
    }

    // Output the permutation
    for (int i = 1; i <= n; ++i) {
