    int total_cycles = 0;

    for (int i = 1; i <= n; i += 2) {
        for (int j = i + 1; j <= n; j += 2) {
            // Add cycle of length 3: i, j, (i + j - 1) % n + 1
            int k = (i + j - 1) % n + 1;
            if (k == i || k == j) continue;
            cycles.push_back({i, j, k});
            total_cycles++;
            // Add cycle of length 3: i, (i + j - 1) % n + 1, j
            cycles.push_back({i, k, j});
