            // Add cycle of length 4: i, j, (i + j + 1) % n + 1, (i + j + 2) % n + 1
            int l = (i + j + 1) % n + 1;
            int m = (i + j + 2) % n + 1;
            if (l == i || l == j || l == k || m == i || m == j || m == k) continue;
            cycles.push_back({i, j, l, m});
            total_cycles++;
            // Add cycle of length 4: i, (i + j + 1) % n + 1, j, (i + j + 2) % n + 1
