    int n;
    cin >> n;
    vector<int> a(n);
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
    }

    deque<int> deck(a.begin(), a.end());
    int count = 0;
    map<int, int> min_pos;

    // Precompute minimum positions
    for (int i = 0; i < n; ++i) {
        min_pos[a[i]] = i;
    }

    while (!deck.empty()) {
        int current_min = *min_element(deck.begin(), deck.end());
        int min_index = min_pos[current_min];

        int steps = 0;
        while (true) {
            if (deck.front() == current_min) {
                ++count;
                deck.pop_front();
                break;
            } else {
                ++count;
                deck.push_back(deck.front());
                deck.pop_front();
            }
        }

        // Update min positions after removing one occurrence of current_min
        min_pos.erase(current_min);
        if (!min_pos.empty()) {
            current_min = *min_pos.begin()->second;
            for (auto it = min_pos.begin(); it != min_pos.end(); ++it) {
                if (it->second < current_min) {
                    current_min = it->second;
                }
            }
            min_pos[current_min] = 0;
        }
    }

    cout << count << endl;
