using namespace std;

int main() {
    string s;
    cin >> s;
    long long n;
    cin >> n;

    char start = s[0];
    char end = s[2];
    long long diff = n % 4;

    // Define the order of positions in clockwise and counter-clockwise directions
    // Clockwise: ^ > v < (0 -> 1 -> 2 -> 3)
    // Counter-clockwise: ^ < v > (0 -> 3 -> 2 -> 1)
    char positions[4] = {'^', '>', 'v', '<'};
    char positions_ccw[4] = {'^', '<', 'v', '>'};

    // Find index of start and end in both directions
    int idx_cw = 0, idx_ccw = 0;
    for (int i = 0; i < 4; ++i) {
        if (positions[i] == start) idx_cw = i;
        if (positions_ccw[i] == start) idx_ccw = i;
    }

    int pos_cw = (idx_cw + diff) % 4;
    int pos_ccw = (idx_ccw + (4 - diff)) % 4;

    if (positions[pos_cw] == end) {
        cout << "cw";
    } else if (positions_ccw[pos_ccw] == end) {
        cout << "ccw";
    } else {
        cout << "undefined";
    }

    return 0;
}

