using namespace std;

int main() {
    int n, x, y;
    cin >> n >> x >> y;

    vector<int> indices(n);
    for (int i = 0; i < n; ++i) indices[i] = i + 1;

    // First query: all icicles
    cout << "? " << n;
    for (int i = 0; i < n; ++i) cout << " " << indices[i];
    cout << endl;
    fflush(stdout);

    int total_xor;
    cin >> total_xor;

    // Find the two special icicles
    vector<int> special;
    for (int i = 0; i < n; ++i) {
        // Query with all but index i
        cout << "? " << n - 1;
        for (int j = 0; j < n; ++j) {
            if (j != i) cout << " " << indices[j];
        }
        cout << endl;
        fflush(stdout);

        int res;
        cin >> res;

        if (res == total_xor ^ y) {
            special.push_back(indices[i]);
        }
    }

    sort(special.begin(), special.end());
    cout << "! " << special[0] << " " << special[1] << endl;
    fflush(stdout);

    return 0;
}

