        adj[u].push_back(v);
        adj[v].push_back(u);
    }

    vector<double> dp(n + 1);
    vector<bool> visited(n + 1);
    queue<int> q;
    q.push(1);
    visited[1] = true;
    dp[1] = 0;

    while (!q.empty()) {
        int u = q.front();
        q.pop();
        for (int v : adj[u]) {
            if (!visited[v]) {
                visited[v] = true;
                dp[v] = dp[u] + 1;
                q.push(v);
            }
        }
    }

    cout << fixed << setprecision(15) << dp[n] << endl;
    return 0;
}
